select *
from b_case_shuhe_user
where is_black = 'Y'
 and upload_date >= #{startDay}
  and upload_date < #{endDay}
group by mobile;

select *
from b_case_shuhe_user


        AND id >=#{minId}


        AND  (clc_usr_max_dx_rrt_end  >=  #{nowDay} or usr_forbid_call_end_tim  >=  #{nowDay})

    order by id asc limit 2000;

select count(*)
from b_case_shuhe_user
where cell = #{cell}
  and (clc_usr_max_dx_rrt_end >= #{localDate}
    or usr_forbid_call_end_tim >=  #{localDate})
